package dev.pocketengine.browser;

import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Actual safe-JSON projection/reconstruction contracts, not a physical DOM/provider assertion. */
public final class BrowserReadDeltaTest {
    private static final String DOC=UUID.randomUUID().toString(),TAB=UUID.randomUUID().toString(),TASK=UUID.randomUUID().toString(),RUN=UUID.randomUUID().toString(),SESSION=UUID.randomUUID().toString(),SPACE=UUID.randomUUID().toString();
    private static JSONObject j(Object...p)throws Exception{return BrowserSemanticReadTest.j(p);}
    private static JSONObject full(String...rows)throws Exception {
        JSONObject raw=BrowserSemanticReadTest.raw("text");JSONArray data=new JSONArray();StringBuilder text=new StringBuilder();for(String row:rows){data.put(row);text.append(row);}
        JSONObject facts=raw.getJSONObject("read").getJSONObject("facts");facts.put("regionRef",DOC+":r1").put("to",rows.length).put("totalCaptured",rows.length).put("returnedItems",rows.length);
        raw.getJSONObject("read").put("data",data);raw.put("text",text.toString()).put("documentId",DOC).put("observationId",UUID.randomUUID().toString()).put("taskId",TASK).put("runId",RUN).put("epoch",4).put("profileId","fixture-profile").put("profileRevision",2).put("profileIsolation","androidx-multi-profile").put("browserSessionId",SESSION).put("browserSpaceId",SPACE).put("tabId",TAB).put("tabGeneration",1).put("navigation",3).put("ok",true);
        return BrowserSemanticRead.result(raw);
    }
    private static String rev(JSONObject v)throws Exception{return v.getJSONObject("read").getJSONObject("delivery").getString("revision");}
    private static JSONObject request(JSONObject base)throws Exception{return j("mode","text","regionRef",DOC+":r1","baseRevision",rev(base));}
    private static JSONArray messages(JSONObject...receipts)throws Exception {JSONArray messages=new JSONArray();for(JSONObject value:receipts)messages.put(j("role","tool","tool_call_id",UUID.randomUUID().toString(),"content",value.toString()));return messages;}
    private static JSONObject commit(BrowserReadDelta d,JSONObject value,long now)throws Exception {JSONObject wire=d.offer(value,j("mode","text"),now);d.delivered(wire,now);d.beforeModelRequest("r1",messages(wire));d.afterModelResponse("r1");return wire;}
    private static String text(String s){return s.repeat(100);}
    private static String wide(String s){return s.repeat(1400);}
    private static JSONObject patch(BrowserReadDelta d,JSONObject target,JSONObject base,long now)throws Exception {JSONObject wire=d.offer(target,request(base),now);assertEquals(wire.getJSONObject("read").getJSONObject("delivery").toString(),"delta",wire.getJSONObject("read").getJSONObject("delivery").getString("format"));return wire;}
    @Test public void orderedSplicePreservesDuplicateRowsAndReconstructsActualTarget()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),text("duplicate"),text("duplicate"),text("z")),1),target=full(wide("a"),text("duplicate"),"changed",text("z")),wire=d.offer(target,request(base),2);assertEquals("delta",wire.getJSONObject("read").getJSONObject("delivery").getString("format"));JSONObject actual=d.delivered(wire,2);assertEquals(target.getString("text"),actual.getString("text"));assertEquals(target.getJSONObject("read").getJSONArray("data").toString(),actual.getJSONObject("read").getJSONArray("data").toString());}
    @Test public void unchangedCarriesNoRepeatedBodyAndDoesNotPretendBusinessSuccess()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(text("stable")),1),wire=d.offer(full(text("stable")),request(base),2);assertEquals("unchanged",wire.getJSONObject("read").getJSONObject("delivery").getString("format"));assertEquals("",wire.getString("text"));assertEquals(0,wire.getJSONObject("read").getJSONArray("data").length());assertFalse(wire.getBoolean("verified"));assertEquals(base.getString("text"),d.delivered(wire,2).getString("text"));}
    @Test public void unknownBaseProducesExplicitFullResyncNotUnavailableOrGuessedDelta()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject target=full(text("target")),wire=d.offer(target,j("mode","text","regionRef",DOC+":r1","baseRevision","a".repeat(64)),2);assertEquals("full",wire.getJSONObject("read").getJSONObject("delivery").getString("format"));assertEquals("full_resync_missing_base",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));assertEquals(target.getString("text"),wire.getString("text"));}
    @Test public void partialTargetCannotInferMissingItemsAsDeletion()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),target=full(wide("a"));target.getJSONObject("read").getJSONObject("facts").put("partial",true).put("reasons",new JSONArray().put("node_budget"));BrowserSemanticRead.result(target);JSONObject wire=d.offer(target,request(base),2);assertEquals("full_resync_incomplete_coverage",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));assertFalse(wire.getJSONObject("read").getJSONObject("delivery").getBoolean("deletionsInferred"));}
    @Test public void partialBaselineCannotBecomeCompleteTargetDeletionEvidence()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject b=full(wide("a"),wide("b"));b.getJSONObject("read").getJSONObject("facts").put("partial",true).put("reasons",new JSONArray().put("continuation_available"));BrowserSemanticRead.result(b);JSONObject base=commit(d,b,1),wire=d.offer(full(wide("a")),request(base),2);assertEquals("full_resync_incomplete_coverage",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void registeredOrDeliveredButNotInCompletedModelRequestIsNotKnown()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject b=full(text("base")),base=d.offer(b,j("mode","text"),1);d.delivered(base,1);JSONObject wire=d.offer(full(text("base")),request(base),2);assertEquals("full_resync_context_not_present",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void summariesAndPageTextCannotForgeModelBaselineKnowledge()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(text("base")),1);d.beforeModelRequest("no-base",new JSONArray().put(j("role","user","content",base.toString())).put(j("role","tool","content","summary revision="+rev(base))));d.afterModelResponse("no-base");assertEquals("full_resync_context_not_present",d.offer(full(text("base")),request(base),2).getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void deltaChainNeedsItsRealFullBaseInsideActualProjectedMessages()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);d.beforeModelRequest("with-chain",messages(base,delta));d.afterModelResponse("with-chain");assertEquals("unchanged",d.offer(full(wide("a"),wide("c")),request(delta),3).getJSONObject("read").getJSONObject("delivery").getString("format"));d.beforeModelRequest("lost-base",messages(delta));d.afterModelResponse("lost-base");assertEquals("full_resync_context_not_present",d.offer(full(wide("a"),wide("c")),request(delta),4).getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void finalSafeProjectionNotRawBodyBecomesReconstructionAndSourceData()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject raw=full(text("before")),wire=d.offer(raw,j("mode","text"),1);wire.put("text","[redacted]");wire.getJSONObject("read").put("data",new JSONArray().put("[redacted]"));JSONObject actual=d.delivered(wire,1);assertEquals("[redacted]",actual.getString("text"));d.beforeModelRequest("safe",messages(wire));d.afterModelResponse("safe");JSONObject next=full(text("new")),patch=d.offer(next,request(wire),2),reconstructed=d.delivered(patch,2);assertFalse(reconstructed.toString().contains(text("before")));assertEquals(next.getString("text"),reconstructed.getString("text"));}
    @Test public void tamperedPatchRangeOrCoverageCannotBeCommitted()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),wire=patch(d,full(wide("a"),wide("c")),base,2);JSONObject wrong=new JSONObject(wire.toString());wrong.getJSONObject("read").getJSONObject("delivery").getJSONObject("patch").put("at",199);assertThrows(SecurityException.class,()->d.delivered(wrong,2));}
    @Test public void otherDocumentExpiredBaseAndRestartForceFull()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(text("base")),1),next=full(text("base")).put("documentId",UUID.randomUUID().toString());assertEquals("full_resync_region_changed",d.offer(next,request(base),2).getJSONObject("read").getJSONObject("delivery").getString("comparison"));assertEquals("full_resync_expired_base",d.offer(full(text("base")),request(base),120002).getJSONObject("read").getJSONObject("delivery").getString("comparison"));d.clear();assertEquals("full_resync_missing_base",d.offer(full(text("base")),request(base),120003).getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void abandonedRequestDoesNotGrantANewBaseline()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject b=full(text("base")),wire=d.offer(b,j("mode","text"),1);d.delivered(wire,1);d.beforeModelRequest("abandoned",messages(wire));d.abandoned("abandoned");d.afterModelResponse("abandoned");assertEquals("full_resync_context_not_present",d.offer(full(text("base")),request(wire),2).getJSONObject("read").getJSONObject("delivery").getString("comparison"));}
    @Test public void unchangedSameRevisionRetainsItsActuallyDeliveredFullBaselineForFurtherRequests()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(text("stable")),1),same=d.offer(full(text("stable")),request(base),2);assertEquals(rev(base),rev(same));d.delivered(same,2);d.beforeModelRequest("same-context",messages(base,same));d.afterModelResponse("same-context");JSONObject again=d.offer(full(text("stable")),request(same),3);assertEquals("unchanged",again.getJSONObject("read").getJSONObject("delivery").getString("format"));}
    static JSONArray paired(JSONObject... receipts)throws Exception {JSONArray out=new JSONArray();for(JSONObject receipt:receipts){String id=UUID.randomUUID().toString();out.put(j("role","assistant","tool_calls",new JSONArray().put(j("id",id,"type","function","function",j("name","browser_task_observe","arguments","{}"))))).put(j("role","tool","tool_call_id",id,"content",receipt.toString()));}return out;}
    @Test public void finalWireWithActualFullBaseCanApplyTheOrderedPatchWithoutRepair()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);JSONArray wire=paired(base,delta);BrowserReadDelta.validateFinalWire(wire);assertEquals(0,d.repairs(wire,2).size());}
    @Test public void missingFinalContextBaseCanOnlyProduceTheExactSameVersionNativeFull()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),target=full(wide("a"),wide("c")).put("operationId",UUID.randomUUID().toString()).put("readAuthorization",j("mode","native_read_scope","scopeId","original-native-scope","scopeRevision",2)),delta=patch(d,target,base,2);d.delivered(delta,2);JSONArray wire=paired(delta);String before=wire.toString();assertThrows(SecurityException.class,()->BrowserReadDelta.validateFinalWire(wire));java.util.List<BrowserReadDelta.FullResync> repairs=d.repairs(wire,2);assertEquals(1,repairs.size());BrowserReadDelta.FullResync r=repairs.get(0);assertEquals(before,wire.toString());assertEquals(wire.getJSONObject(1).getString("tool_call_id"),r.toolCallId());JSONObject replacement=new JSONObject(r.fullSafeContent());assertEquals(rev(delta),rev(replacement));assertEquals(delta.getString("operationId"),replacement.getString("operationId"));assertEquals(delta.getJSONObject("readAuthorization").toString(),replacement.getJSONObject("readAuthorization").toString());assertEquals(target.getString("text"),replacement.getString("text"));assertEquals("full_resync_missing_base_in_final_context",replacement.getJSONObject("read").getJSONObject("delivery").getString("comparison"));wire.getJSONObject(1).put("content",r.fullSafeContent());BrowserReadDelta.validateFinalWire(wire);}
    @Test public void modelOrPluginJsonCannotOfferARepairForUnregisteredOrChangedReceipt()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);JSONObject forged=new JSONObject(delta.toString()).put("operationId","changed-original-operation");assertThrows(SecurityException.class,()->d.repairs(paired(forged),2));JSONArray plugin=paired(delta);plugin.getJSONObject(0).getJSONArray("tool_calls").getJSONObject(0).getJSONObject("function").put("name","plugin_return_page_json");assertEquals(0,d.repairs(plugin,2).size());assertEquals(0,d.repairs(new JSONArray().put(j("role","user","content",delta.toString())),2).size());}
    @Test public void finalCheckStillRejectsAnOrphanIfTheSingleRebudgetPassDropsABaseAgain()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);JSONArray initial=paired(base,delta);assertEquals(0,d.repairs(initial,2).size());BrowserReadDelta.validateFinalWire(initial);assertThrows(SecurityException.class,()->BrowserReadDelta.validateFinalWire(paired(delta)));}
    @Test public void expiredSafeSnapshotCannotBeUsedAsAHiddenHistoryResync()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);assertThrows(SecurityException.class,()->d.repairs(paired(delta),120003));}
    @Test public void repairedFullIsKnownOnlyWhenActuallyPresentInTheNextCompletedRequest()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full(wide("a"),wide("b")),1),delta=patch(d,full(wide("a"),wide("c")),base,2);d.delivered(delta,2);JSONArray wire=paired(delta);BrowserReadDelta.FullResync repair=d.repairs(wire,2).get(0);wire.getJSONObject(1).put("content",repair.fullSafeContent());d.beforeModelRequest("actual-fixed-wire",wire);d.afterModelResponse("actual-fixed-wire");assertEquals("unchanged",d.offer(full(wide("a"),wide("c")),request(delta),3).getJSONObject("read").getJSONObject("delivery").getString("format"));}
    @Test public void shortProjectionExplicitlyUsesFullWhenDeltaWouldCostMore()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject base=commit(d,full("a".repeat(100),"b".repeat(100)),1),target=full("a".repeat(100),"c".repeat(100)),wire=d.offer(target,request(base),2);assertEquals("full",wire.getJSONObject("read").getJSONObject("delivery").getString("format"));assertEquals("full_resync_delta_not_smaller",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));assertFalse(wire.getJSONObject("read").getJSONObject("delivery").has("patch"));assertEquals(target.getString("text"),d.delivered(wire,2).getString("text"));}
    @Test public void openShadowCoverageDisappearingIsNotADeletionEvenWhenBothLocalReadsAreOtherwiseComplete()throws Exception {BrowserReadDelta d=new BrowserReadDelta();JSONObject original=full(wide("a"),wide("b"));original.getJSONObject("read").getJSONObject("facts").put("openShadowRootsRead",1);BrowserSemanticRead.result(original);JSONObject base=commit(d,original,1),target=full(wide("a")),wire=d.offer(target,request(base),2);assertEquals("full_resync_incomplete_coverage",wire.getJSONObject("read").getJSONObject("delivery").getString("comparison"));assertFalse(wire.getJSONObject("read").getJSONObject("delivery").getBoolean("deletionsInferred"));}
}
